import {escapeHtml as e} from './core.js?v=d9b04d29540c';
import {studyPlan,searchCatalog,reviewEntries} from './study.js?v=d9b04d29540c';

export function dashboard(state,englishSupport){
 const plan=studyPlan(state);
 return `<section class="study-dashboard" aria-labelledby="daily-title"><div class="daily-plan"><div class="daily-plan-header"><div><p class="eyebrow">UNA SESIÓN A TU MEDIDA</p><h2 id="daily-title">¿Qué estudio hoy?</h2><p>Tu ruta ${state.level}, en tres pasos pequeños.</p></div><label>Hoy tengo<select id="session-minutes">${[10,15,25].map(n=>`<option value="${n}" ${n===plan.minutes?'selected':''}>${n} minutos</option>`).join('')}</select></label></div><ol class="daily-steps">${plan.steps.map((step,i)=>`<li class="daily-step"><span class="daily-step-number" aria-hidden="true">0${i+1}</span><div class="daily-step-body"><span class="daily-step-meta">${step.minutes} MIN · ${['RECUERDA','ENTIENDE','APLICA'][i]}</span><h3><a href="${e(step.href)}">${e(step.title)} →</a></h3><p>${e(step.description)}</p></div></li>`).join('')}</ol><p class="tiny">Los tiempos orientan: termina donde te quedes y continúa otro día.</p>${englishSupport('Choose the time you have. Recall something first, work on one grammar contrast, then read or listen. You do not need to finish a whole lesson in one session. B1 is your starting route; A2 is always available for support.')}</div><div class="quick-actions"><a href="#search"><strong>Encuentra lo que necesitas →</strong><span>Busca temas en español o inglés.</span></a><a href="#review"><strong>${plan.due?`${plan.due} preguntas para repasar`:'Tu espacio de repaso'} →</strong><span>Recupera los errores a tu ritmo.</span></a><a href="#route/A2"><strong>Una base más clara · A2 →</strong><span>Refuerza un tema cuando B1 se complique.</span></a></div></section>`;
}
export function searchResults(query,options){
 const items=searchCatalog(query,options);
 return {count:items.length,html:items.length?items.map(item=>`<a class="search-result" href="${e(item.href)}"><div><span class="badge level-${item.level}">${item.level}</span><span class="tiny">${e(item.kind)}</span></div><h2>${e(item.title)}</h2><p>${e(item.description.length>170?item.description.slice(0,167)+'…':item.description)}</p><span>Abrir →</span></a>`).join(''):'<div class="review-empty"><h2>No encontramos ese contenido</h2><p>Prueba una palabra más corta, busca en todos los niveles o cambia de idioma: «pasado», «past», «pronombres»…</p></div>'};
}
export function searchPage(state,englishSupport){
 const result=searchResults('',{level:state.level,currentLevel:state.level});
 return `<p class="eyebrow">TODOS TUS RECURSOS, A MANO</p><h1>Busca tu próximo paso.</h1><p class="lead">Unidades, reglas, lecturas y esquemas. Escribe en español o en inglés.</p>${englishSupport('Search in Spanish or English, then narrow the results by level or activity. Written accents are optional in search; ñ remains a separate letter. All levels are open.')}<div class="study-search"><label for="catalog-query">Qué quieres practicar<input id="catalog-query" type="search" maxlength="180" placeholder="Pasado, past tense, pronouns…" autocomplete="off"></label><label for="catalog-level">Nivel<select id="catalog-level"><option value="all">Todos los niveles</option>${['A2','B1','B2','C1'].map(l=>`<option ${state.level===l?'selected':''}>${l}</option>`).join('')}</select></label><label for="catalog-type">Actividad<select id="catalog-type"><option value="all">Todas las actividades</option><option value="lesson">Unidades</option><option value="grammar">Fichas de gramática</option><option value="reading">Lectura y escucha</option><option value="visual">Esquemas visuales</option></select></label></div><p id="search-count" role="status" aria-live="polite">${result.count} recursos disponibles</p><div id="catalog-results" class="search-results">${result.html}</div>`;
}
export function reviewPage(state,englishSupport,quizMarkup,seen=new Set()){
 const all=reviewEntries(state),due=all.filter(q=>q.dueNow),batch=[...due.filter(q=>!seen.has(q.key)),...due.filter(q=>seen.has(q.key))].slice(0,8),next=all.find(q=>!q.dueNow);
 return `<p class="eyebrow">RECORDAR, CORREGIR, VOLVER</p><h1>${state.level} · Mi repaso</h1><p class="lead">Una segunda oportunidad para los contrastes que te costaron.</p>${englishSupport('Mistakes from corrected activities are collected here. Answer before checking the explanation. Correct reviews return after 1, 3, 7 and 14 days; a mistake is available again today. These are flexible study intervals, not a level test.')}<div class="review-summary"><div><strong>${due.length}</strong><span>para repasar hoy</span></div><div><strong>${all.length-due.length}</strong><span>para días siguientes</span></div></div>${batch.length?`<h2>Una tanda de ${batch.length} preguntas</h2><p>Intenta recordar la regla. Después escribe una frase nueva para comprobar que puedes usarla.</p>${quizMarkup(`review/${state.level}`,batch.map(q=>q.question),batch.map(q=>q.key))}`:`<div class="review-empty"><h2>${all.length?'Por hoy, repaso al día.':'Aquí aparecerán tus errores útiles.'}</h2><p>${next?`El próximo repaso está previsto para ${e(next.due.split('-').reverse().join('/'))}. Puedes seguir explorando mientras tanto.`:'Corrige una unidad, una lectura o un tema de gramática. Sus preguntas falladas se guardarán para volver a practicarlas.'}</p><a class="button" href="#grammar">Practicar un tema →</a></div>`}<details><summary>Cómo funciona este repaso</summary><p>Al acertar una pregunta pendiente, vuelve dentro de 1, 3, 7 y después 14 días. Si fallas, vuelve a estar disponible hoy. Los intervalos son una ayuda ajustable a tu ritmo; no miden dominio ni nivel. Un acierto antes de la fecha prevista no alarga el intervalo.</p><p>El historial antiguo de gramática se incorpora cuando conserva respuestas. Los resultados antiguos sin respuestas no permiten reconstruir qué preguntas fallaste.</p><p>Las respuestas en curso de estas tandas no se conservan al salir; las de unidades y controles sí. Cada tanda vuelve a seleccionar hasta ocho preguntas pendientes.</p></details><a href="#home">← Volver a mi estudio</a>`;
}
